// context/LanguageContext.tsx
"use client";
import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  ReactNode,
} from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Loader2 } from 'lucide-react';

// List of supported languages (you can expand later)
export const SUPPORTED_LANGUAGES = [
  { code: 'en', label: 'English' },
  { code: 'ky', label: 'Ikinyarwanda' },     // Kinyarwanda
  { code: 'fr', label: 'Français' },
] as const;

export type LanguageCode = typeof SUPPORTED_LANGUAGES[number]['code'];

// Type for the context value
type LanguageContextType = {
  currentLanguage: LanguageCode;
  setLanguage: (lang: LanguageCode) => Promise<void>;
  isLoading: boolean;
};

// Default/fallback language
const DEFAULT_LANGUAGE: LanguageCode = 'en';

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [currentLanguage, setCurrentLanguage] = useState<LanguageCode>(DEFAULT_LANGUAGE);
  const [isLoading, setIsLoading] = useState(true);

  // Load saved language on mount
  useEffect(() => {
    
    const loadLanguage = async () => {
      setIsLoading(true);
      try {
        const savedLang = await AsyncStorage.getItem('language');
        if (savedLang ) {
          setCurrentLanguage(savedLang as LanguageCode);
        }else{
          setCurrentLanguage(DEFAULT_LANGUAGE);
        }
        // else → keep default 'en'
      } catch (e) {
        console.log('Failed to load language preference:', e);
      } finally {
        setIsLoading(false);
      }
    };

    loadLanguage();
  }, []);

  // Change language + persist
  const setLanguage = async (lang: LanguageCode) => {
    try {
      await AsyncStorage.setItem('language', lang);
      setCurrentLanguage(lang);
    } catch (e) {
      console.log('Failed to save language preference:', e);
    }
  };

  const value: LanguageContextType = {
    currentLanguage,
    setLanguage,
    isLoading,
  };

  return (
    <LanguageContext.Provider value={value}>
     {isLoading ? <div className="flex items-center justify-center h-screen">
<Loader2 className='animate-spin'/>
     </div> : children}
    </LanguageContext.Provider>
  );
}

// Custom hook - recommended way to use the context
export function useLanguage() {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
}